<template><AppShell><StatePanel v-if="loading||error" :loading="loading" :error="error" @retry="load"/><template v-else-if="data"><view class="home-hero"><image class="hero-landscape" src="/static/landscape.svg" mode="aspectFill"/><view class="hero-copy"><text class="eyebrow">英迹 · 山河英雄谱</text><text class="hero-title">循山河之迹<text class="title-line">读时代之人</text></text><text class="hero-description">从一位人物开始，沿着年代与史料，<text class="title-line">走近历史中的真实片段。</text></text><button class="primary hero-cta" @tap="go('people')">开启人物之旅 <text>↗</text></button><text class="hero-caption">原创山水意象 · 非历史地理示意</text></view><view class="hero-label"><text>山河有迹</text><text>史料有据</text></view></view><view class="opening-strip"><view><text class="count-number">{{data.meta.people_count}}</text><text>位收录人物</text></view><view><text class="strip-word">循迹</text><text>读人物与时代</text></view><view><text class="strip-word">见史</text><text>每段阅读可溯源</text></view><text class="scope-note">本批资料范围<br/>完整生平持续整理中</text></view><view class="section-heading"><view><text class="eyebrow">01 / 人物专题</text><text class="section-title">一段人生，一页时代</text></view><button class="text-button" @tap="go('people')">全部人物 ↗</button></view><view class="featured-grid"><PersonCard v-for="(p,i) in data.featured_people.slice(0,3)" :key="p.id" :person="p" :index="i" :featured="i===0"/></view><view class="longroll-banner" @tap="go('timeline')"><view><text class="eyebrow">02 / 山河长卷</text><text class="banner-title">把散落的片段<text class="title-line">放回时间之中</text></text><text class="banner-description">按人物、年份与阶段，展开有史料依据的阅读长卷。</text><button class="light-button" @tap.stop="go('timeline')">展开长卷 ↗</button></view><view class="roll-mark"><text>一</text><text>九</text><text>一</text><text>六</text><text class="roll-note">年代，是进入故事的另一扇门</text></view></view><view class="section-heading"><view><text class="eyebrow">03 / 史料片段</text><text class="section-title">从一件事，读懂一个人</text></view></view><view class="home-events"><view v-for="e in data.events.slice(0,3)" :key="e.id" class="event-teaser" @tap="go('event',{id:e.id})"><text class="event-year">{{e.date_text}}</text><text class="teaser-title">{{e.title}}</text><text class="muted">{{e.person_name||''}}</text><text class="teaser-summary">{{e.summary}}</text><text class="teaser-link">阅读片段 ↗</text></view></view><view class="module-section"><text class="eyebrow">更多入口</text><view class="module-grid"><button v-for="m in modules" :key="m.name" @tap="m.route?go(m.route):connected(m.name)"><image :src="'/static/icons/'+m.icon+'.svg'"/><text>{{m.name}}</text><text class="module-caption">{{m.caption}}</text></button></view></view><view v-if="recent.length" class="recent-inline"><text class="eyebrow">接着上次阅读</text><button @tap="go(recent[0].kind,{id:recent[0].id})">{{recent[0].title}} <text>继续阅读 ↗</text></button></view></template></AppShell></template>
<script setup>
import {ref} from 'vue';import {onShow,onShareAppMessage} from '@dcloudio/uni-app';import AppShell from '../../components/AppShell.vue';import PersonCard from '../../components/PersonCard.vue';import StatePanel from '../../components/StatePanel.vue';import {api} from '../../lib/api.js';import {go,connected} from '../../lib/navigation.js';import {history} from '../../lib/reading.js'
const data=ref(null),loading=ref(true),error=ref(''),recent=ref([])
const modules=[{name:'山河',icon:'home',caption:'时间与事迹',route:'timeline'},{name:'人物',icon:'people',caption:'人物专题',route:'people'},{name:'足迹',icon:'pin',caption:'待接入'},{name:'互动',icon:'graph',caption:'待接入'},{name:'文创',icon:'book',caption:'待接入'},{name:'我的',icon:'bookmark',caption:'本机阅读',route:'me'}]
async function load(){loading.value=true;error.value='';try{data.value=await api('home')}catch(e){error.value=e.message}finally{loading.value=false}}
onShow(()=>{recent.value=history();if(!data.value)load()});onShareAppMessage(()=>({title:'英迹 · 循迹读人，见史山河',path:'/pages/home/index'}))
</script>
